import itertools
import json

def solve_puzzle():
    houses = [1, 2, 3]

    # Attributes as per puzzle
    names = ['Eric', 'Peter', 'Arnold']
    drinks = ['tea', 'water', 'milk']
    nationalities = ['dane', 'brit', 'swede']
    education_levels = ['high school', 'associate', 'bachelor']
    house_styles = ['victorian', 'colonial', 'ranch']
    smoothies = ['cherry', 'watermelon', 'desert']

    def pos_of(seq, value):
        return seq.index(value)

    solutions = []

    for name_perm in itertools.permutations(names):
        # No early constraint solely on names
        for drink_perm in itertools.permutations(drinks):
            # Clue 1: There is one house between Eric and the tea drinker.
            if abs(pos_of(name_perm, 'Eric') - pos_of(drink_perm, 'tea')) != 2:
                continue

            for style_perm in itertools.permutations(house_styles):
                # Clue 6: The person residing in a Victorian house is not in the first house.
                if style_perm[0] == 'victorian':
                    continue
                # Clue 8: Arnold is somewhere to the right of the person residing in a Victorian house.
                if pos_of(name_perm, 'Arnold') <= pos_of(style_perm, 'victorian'):
                    continue
                # Clue 2: The person who likes milk is the person in a ranch-style home.
                if pos_of(drink_perm, 'milk') != pos_of(style_perm, 'ranch'):
                    continue

                for edu_perm in itertools.permutations(education_levels):
                    # Clue 3: The person with a bachelor's degree is in the second house.
                    if edu_perm[1] != 'bachelor':
                        continue
                    # Clue 9: The person in a ranch-style home is the person with a high school diploma.
                    if pos_of(style_perm, 'ranch') != pos_of(edu_perm, 'high school'):
                        continue

                    for nat_perm in itertools.permutations(nationalities):
                        # Clue 4: The person with a high school diploma is the Dane.
                        if pos_of(edu_perm, 'high school') != pos_of(nat_perm, 'dane'):
                            continue

                        for smoothie_perm in itertools.permutations(smoothies):
                            # Clue 5: The Desert smoothie lover is the Swedish person.
                            if pos_of(smoothie_perm, 'desert') != pos_of(nat_perm, 'swede'):
                                continue
                            # Clue 7: The person who likes Cherry smoothies is the person living in a colonial-style house.
                            if pos_of(smoothie_perm, 'cherry') != pos_of(style_perm, 'colonial'):
                                continue

                            # If all constraints satisfied, record solution
                            solutions.append({
                                'names': name_perm,
                                'drinks': drink_perm,
                                'nationalities': nat_perm,
                                'education': edu_perm,
                                'styles': style_perm,
                                'smoothies': smoothie_perm
                            })

    if not solutions:
        raise RuntimeError("No solution found")

    # Assuming unique solution for standard Zebra puzzles; take the first
    sol = solutions[0]

    header = ["House", "Name", "favorite drink", "nationalities", "level of education", "style of house", "favorite smoothie"]
    rows = []
    for i in range(3):
        rows.append([
            str(i + 1),
            sol['names'][i],
            sol['drinks'][i],
            sol['nationalities'][i],
            sol['education'][i],
            sol['styles'][i],
            sol['smoothies'][i],
        ])

    output = {
        "solution": {
            "header": header,
            "rows": rows
        }
    }
    print(json.dumps(output, ensure_ascii=False))


if __name__ == "__main__":
    solve_puzzle()
